css:
.nudgesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #16323a;
    background: linear-gradient(165deg, #eef6f6 0%, #e6f1f2 55%, #e0eef0 100%);
    border-radius: 18px;
}

.nudgesim-container * {
    box-sizing: border-box;
}

.nudgesim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #06363f 0%, #0a6273 52%, #0f9aa0 100%);
    color: #effbfa;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(6, 54, 63, 0.32);
}

.nudgesim-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.nudgesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd27a;
    background: rgba(255, 210, 122, 0.14);
    border: 1px solid rgba(255, 210, 122, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.nudgesim-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfeceb;
}

.nudgesim-segments {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.nudgesim-segment {
    background: #ffffff;
    border-radius: 14px;
    padding: 13px 15px;
    box-shadow: 0 4px 14px rgba(16, 50, 58, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-top: 4px solid #0a6273;
}

.nudgesim-segment-pay { border-top-color: #1f9d8a; }
.nudgesim-segment-restrict { border-top-color: #2f7fc4; }
.nudgesim-segment-meter { border-top-color: #6f5fc0; }
.nudgesim-segment-fraud { border-top-color: #d9772e; }

.nudgesim-segment-name {
    font-weight: 800;
    font-size: 0.98rem;
    color: #06363f;
}

.nudgesim-segment-meta {
    font-size: 0.78rem;
    color: #5a6f78;
    line-height: 1.4;
}

.nudgesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3c545d;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.nudgesim-period-counter #currentDay,
.nudgesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f9aa0;
}

.nudgesim-round-name {
    background: rgba(15, 154, 160, 0.14);
    color: #0a6273;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.nudgesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b06317;
    background: rgba(217, 119, 46, 0.14);
    border: 1px solid rgba(217, 119, 46, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.nudgesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.nudgesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(16, 50, 58, 0.08);
    border-top: 4px solid #0a6273;
}

.nudgesim-card-uplift { border-top-color: #1f9d8a; }
.nudgesim-card-bci { border-top-color: #0f9aa0; }
.nudgesim-card-adopt { border-top-color: #2f7fc4; }
.nudgesim-card-budget { border-top-color: #d9772e; }

.nudgesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #667c85;
}

.nudgesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #06363f;
    font-variant-numeric: tabular-nums;
}

.nudgesim-card-uplift .nudgesim-value { color: #16876f; }
.nudgesim-card-bci .nudgesim-value { color: #0f9aa0; }
.nudgesim-card-adopt .nudgesim-value { color: #2f7fc4; }
.nudgesim-card-budget .nudgesim-value { color: #c2671a; }

.nudgesim-sublabel {
    font-size: 0.76rem;
    color: #748b94;
    line-height: 1.35;
}

.nudgesim-card-uplift.nudgesim-uplift-danger { border-top-color: #d64545; }
.nudgesim-card-uplift.nudgesim-uplift-danger .nudgesim-value { color: #d64545; }
.nudgesim-card-uplift.nudgesim-uplift-good { border-top-color: #16876f; }
.nudgesim-card-budget.nudgesim-budget-danger { border-top-color: #d64545; }
.nudgesim-card-budget.nudgesim-budget-danger .nudgesim-value { color: #d64545; }

.nudgesim-standing-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #d9e4e6;
    color: #3c545d;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.nudgesim-standing-bar #standingDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #d64545;
    font-weight: 800;
}

.nudgesim-standing-bar.nudgesim-standing-good #standingDisplay { color: #16876f; }
.nudgesim-standing-bar.nudgesim-standing-mid #standingDisplay { color: #c2671a; }

.nudgesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #0f9aa0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(16, 50, 58, 0.07);
}

.nudgesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.nudgesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #06363f;
    margin-bottom: 6px;
}

.nudgesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34505a;
}

.nudgesim-briefing-text strong { color: #0a6273; }
.nudgesim-briefing-text em { color: #c2671a; font-style: italic; }

.nudgesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(16, 50, 58, 0.07);
}

.nudgesim-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #06363f;
    border-bottom: 2px solid #e4ecee;
    padding-bottom: 8px;
}

.nudgesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28424c;
    margin: 14px 0 6px;
}

.nudgesim-container select,
.nudgesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c3d2d6;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #16323a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.nudgesim-container select:focus,
.nudgesim-container input[type="number"]:focus {
    outline: none;
    border-color: #0f9aa0;
    box-shadow: 0 0 0 3px rgba(15, 154, 160, 0.16);
}

.nudgesim-container select option {
    background-color: #ffffff;
    color: #16323a;
}

.nudgesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #0f9aa0;
}

.nudgesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #3c545d;
    margin-top: 4px;
}

.nudgesim-range-readout span:nth-child(2) {
    color: #0f9aa0;
    font-weight: 800;
}

.nudgesim-hint {
    font-size: 0.8rem;
    color: #748b94;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.nudgesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.nudgesim-container .btn-primary {
    background: linear-gradient(135deg, #0a6273 0%, #0f9aa0 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(10, 98, 115, 0.32);
}

.nudgesim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.nudgesim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c3d2d6;
    color: #5a6f78;
    background: transparent;
}

.nudgesim-coach {
    background: linear-gradient(160deg, #06363f 0%, #0a4351 100%);
    color: #dff2f0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(6, 54, 63, 0.26);
}

.nudgesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd27a;
    margin-bottom: 8px;
}

.nudgesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.nudgesim-coach-body strong { color: #6fe0d0; }
.nudgesim-coach-body em { color: #ffd27a; font-style: italic; }

.nudgesim-history,
.nudgesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(16, 50, 58, 0.07);
}

.nudgesim-history h3,
.nudgesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #06363f;
}

.nudgesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #34505a;
}

.nudgesim-container table#usfHistoryTable th {
    background: #e9f3f2;
    color: #0a6273;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d3e2e0;
}

.nudgesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eaf0f1;
    color: #34505a;
}

.nudgesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6faf9;
}

.nudgesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .nudgesim-container {
        padding: 14px;
    }
    .nudgesim-header h1 {
        font-size: 1.7rem;
    }
    .nudgesim-segments {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .nudgesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .nudgesim-value {
        font-size: 2rem;
    }
    .nudgesim-clock {
        margin-left: 0;
    }
    .nudgesim-period-counter {
        font-size: 0.88rem;
    }
    .nudgesim-standing-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .nudgesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (ntc- prefix; matches the teal BMU theme) ---- */
.ntc-completion { padding: 8px 4px 4px; }
.ntc-cm-head { text-align: center; margin-bottom: 16px; }
.ntc-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #16876f; }
.ntc-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6b8189; }
.ntc-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #10323a; }
.ntc-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.ntc-cm-yes { background: rgba(22,135,111,0.14); color: #16876f; border: 1px solid rgba(22,135,111,0.45); }
.ntc-cm-mid { background: rgba(47,127,196,0.12); color: #2f7fc4; border: 1px solid rgba(47,127,196,0.40); }
.ntc-cm-no  { background: rgba(200,64,52,0.12); color: #c84034; border: 1px solid rgba(200,64,52,0.42); }
.ntc-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.ntc-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(15,154,160,0.07); border: 1px solid rgba(15,154,160,0.20); border-radius: 10px; padding: 10px 8px; text-align: center; }
.ntc-cm-mv { display: block; font-size: 1.25rem; font-weight: 800; color: #0f9aa0; }
.ntc-cm-ml { display: block; font-size: 0.70rem; margin-top: 4px; color: #6b8189; text-transform: uppercase; letter-spacing: 0.03em; }
.ntc-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #10323a; }
.ntc-cm-insights { margin: 0; padding-left: 20px; }
.ntc-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #3c545d; }

