(function() {
    'use strict';

    class NudgeToComplyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Nudge to Comply`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Brisbane Metro Utilities).
            this.BUDGET_CAP = 3.0;        // A$3M capped pilot budget
            this.START_STANDING = 30;     // regulator & trust standing 0–100 (higher safer)
            this.START_BCI = 38;          // behaviour-change index baseline
            this.PENALTY = 5;             // A$5M penalty exposure
            this.ENFORCE_COST = 6.8;      // A$6.8M/yr enforcement cost
            this.UPLIFT_TARGET = 8;       // the credible uplift the board wants (pp)

            // Concept truths.
            this.TRUE_TARGET = `payment`;
            this.TRUE_MECH = `enabling`;
            this.TRUE_CHANNEL = `blended`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    uplift: 0,                       // projected compliance uplift (pp)
                    bci: this.START_BCI,             // behaviour-change index 0–100
                    adoption: 0,                     // adoption rate (% of target reached & moved)
                    budgetLeft: this.BUDGET_CAP,     // A$M remaining of the 3.0 cap
                    spent: 0,                        // A$M committed
                    standing: this.START_STANDING,   // regulator & trust standing 0–100
                    // ---- Sticky run-defining error flags (set when committed; gate the verdict). ----
                    oneSizeRun: false,               // one nudge for all / no can't-vs-won't split
                    coercionRun: false,              // disguised enforcement branded as a nudge
                    channelMismatchRun: false,       // digital nudge for a non-digital audience
                    noControlRun: false,             // broad rollout with no counterfactual
                    backfireScaled: false,           // scaled a nudge that backfired
                    misTargeted: false,              // aimed an enabling nudge at the won't-comply segment
                    diagnosisLed: false,             // ran a genuine COM-B diagnosis
                    ethicsClean: false,              // passed a full ethics check
                    upliftHistory: [0],
                    bciHistory: [this.START_BCI],
                    adoptionHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    target: `fraud`,
                    diagnosis: `moral`,
                    lens: `intuition`,
                    segment: 35,
                    mechanism: `threat`,
                    channel: `digital`,
                    ethics: `skip`,
                    invest: 200000,
                    scope: `broad`,
                    control: `none`,
                    enforce: `dropall`,
                    speed: 70,
                    read: `average`,
                    scale: `scaleall`,
                    pitch: `spin`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ta = document.getElementById(`targetInput`);
                const di = document.getElementById(`diagnosisInput`);
                const le = document.getElementById(`lensInput`);
                const se = document.getElementById(`segmentInput`);
                if (ta) decisions.target = ta.value;
                if (di) decisions.diagnosis = di.value;
                if (le) decisions.lens = le.value;
                if (se) decisions.segment = parseInt(se.value, 10);
                if (!Number.isFinite(decisions.segment) || decisions.segment < 0 || decisions.segment > 100) {
                    warn(`warn_segment_range`); return false;
                }
            } else if (round === 2) {
                const me = document.getElementById(`mechanismInput`);
                const ch = document.getElementById(`channelInput`);
                const et = document.getElementById(`ethicsInput`);
                const inv = document.getElementById(`investInput`);
                if (me) decisions.mechanism = me.value;
                if (ch) decisions.channel = ch.value;
                if (et) decisions.ethics = et.value;
                if (inv) decisions.invest = parseInt(inv.value, 10);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0) {
                    warn(`warn_invest_value`); return false;
                }
            } else if (round === 3) {
                const sc = document.getElementById(`scopeInput`);
                const co = document.getElementById(`controlInput`);
                const en = document.getElementById(`enforceInput`);
                const sp = document.getElementById(`speedInput`);
                if (sc) decisions.scope = sc.value;
                if (co) decisions.control = co.value;
                if (en) decisions.enforce = en.value;
                if (sp) decisions.speed = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.speed) || decisions.speed < 0 || decisions.speed > 100) {
                    warn(`warn_speed_range`); return false;
                }
            } else if (round === 4) {
                const re = document.getElementById(`readInput`);
                const sca = document.getElementById(`scaleInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (re) decisions.read = re.value;
                if (sca) decisions.scale = sca.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let upliftDelta = 0, bciDelta = 0, adoptionDelta = 0, standingDelta = 0;
            let spendThisRound = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Round 1 — Diagnose. Choose a target and read the drivers (Common Error 1).
                switch (d.target) {
                    case `payment`:
                        // Largest dollar problem, mostly can't-comply — a nudge can move it fast.
                        bciDelta += 6; upliftDelta += 1; coachKey = `coach_r1_payment`; break;
                    case `restriction`:
                        // Chasing the headline; mixed segment, harder to move cleanly.
                        bciDelta += 1; coachKey = `coach_r1_restriction`; break;
                    case `fraud`:
                        // Aiming the pilot at the deliberate won't-comply core first — enabling nudges backfire here.
                        ds.misTargeted = true; bciDelta -= 6; standingDelta -= 4; coachKey = `coach_r1_fraud`; break;
                    case `all`:
                        // One campaign for four different behaviours = the one-size error in disguise.
                        ds.oneSizeRun = true; bciDelta -= 8; upliftDelta -= 1; coachKey = `coach_r1_all`; break;
                }

                switch (d.diagnosis) {
                    case `split`:
                        // The modelled move: separate can't-comply from won't-comply via COM-B.
                        ds.diagnosisLed = true; bciDelta += 12; standingDelta += 4; coachKey = `coach_r1_split`; break;
                    case `onebucket`:
                        // One bucket = the one-size diagnosis; the same intervention can't fit opposite drivers.
                        ds.oneSizeRun = true; bciDelta -= 8; coachKey = `coach_r1_onebucket`; break;
                    case `moral`:
                        // "They just won't" reproduces the punitive framing that caused the crisis.
                        bciDelta -= 6; standingDelta -= 3; coachKey = `coach_r1_moral`; break;
                }

                switch (d.lens) {
                    case `comb`: bciDelta += 6; standingDelta += 2; if (d.diagnosis === `split`) coachKey = `coach_r1_sharp`; break;
                    case `enforcement`: bciDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r1_enforcelens` : coachKey; break;
                    case `intuition`: bciDelta -= 3; break;
                }

                // Segmentation rigour buffers later design quality.
                if (d.segment >= 60) { bciDelta += 5; }
                else if (d.segment <= 20) { bciDelta -= 3; }

                summaryKey = (d.diagnosis === `split` && d.lens === `comb` && (d.target === `payment` || d.target === `restriction`)) ? `sum_r1_good` :
                             (ds.oneSizeRun ? `sum_r1_onesize` :
                             (d.diagnosis === `moral` ? `sum_r1_moral` : `sum_r1_weak`));
            } else if (round === 2) {
                // Round 2 — Design the intervention (Common Errors 2 & 3).
                const reachable = d.target === `restriction`; // mainly digitally reachable
                // (a) Mechanism.
                switch (d.mechanism) {
                    case `enabling`:
                        // Friction reduction + opt-out default + timely salience — fits the can't-comply core.
                        if (ds.misTargeted || ds.oneSizeRun) { upliftDelta += 2; bciDelta += 3; }
                        else { upliftDelta += 6; bciDelta += 8; standingDelta += 3; }
                        coachKey = `coach_r2_enabling`; break;
                    case `socialnorm`:
                        // Works on the mainstream but seeds a boomerang risk on low-volume / won't-comply.
                        upliftDelta += 3; bciDelta += 2; coachKey = `coach_r2_socialnorm`; break;
                    case `threat`:
                        // A countdown-to-disconnection SMS is enforcement in a smaller font — the crisis, again.
                        ds.coercionRun = true; upliftDelta += 1; standingDelta -= 12; bciDelta -= 6; coachKey = `coach_r2_threat`; break;
                    case `commitment`:
                        // A pledge with no support attached asks the can't-comply to promise what they can't do.
                        upliftDelta += 1; bciDelta -= 2; coachKey = `coach_r2_commitment`; break;
                }

                // (b) Channel-fit (decision tree #3). The payment / hardship core is largely low-digital.
                switch (d.channel) {
                    case `blended`:
                        adoptionDelta += 52; bciDelta += 6; standingDelta += 2; break;
                    case `human`:
                        adoptionDelta += 42; bciDelta += 3; break;
                    case `digital`:
                        if (reachable) { adoptionDelta += 48; bciDelta += 2; }
                        else { ds.channelMismatchRun = true; adoptionDelta += 8; bciDelta -= 6; standingDelta -= 2; coachKey = `coach_r2_channelmiss`; }
                        break;
                }

                // (c) Ethics check (decision tree #2 / Common Error 2).
                switch (d.ethics) {
                    case `full`:
                        ds.ethicsClean = true; standingDelta += 8; bciDelta += 6;
                        if (d.mechanism === `enabling` && d.channel === `blended`) coachKey = `coach_r2_clean`;
                        break;
                    case `disguise`:
                        // Softening a threat is still coercion — the line the case turns on.
                        ds.coercionRun = true; standingDelta -= 8; bciDelta -= 4; coachKey = `coach_r2_disguise`; break;
                    case `skip`:
                        standingDelta -= 4; bciDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r2_skipethics`; break;
                }

                spendThisRound = (d.invest || 0) / 1000000; // A$ -> A$M
                if (d.invest >= 1400000) { bciDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_gold` : coachKey; }
                else if (d.invest >= 600000) { bciDelta += 3; adoptionDelta += 4; }
                else { adoptionDelta -= 4; }

                summaryKey = (d.mechanism === `enabling` && d.channel === `blended` && d.ethics === `full`) ? `sum_r2_good` :
                             (ds.coercionRun ? `sum_r2_coercion` :
                             (ds.channelMismatchRun ? `sum_r2_channel` : `sum_r2_weak`));
            } else if (round === 3) {
                // Round 3 — Rollout scope & test design (Common Error 4).
                switch (d.scope) {
                    case `multiarm`:
                        bciDelta += 10; standingDelta += 4; upliftDelta += 1; spendThisRound += 0.9; coachKey = `coach_r3_multiarm`; break;
                    case `pilot`:
                        bciDelta += 9; standingDelta += 4; spendThisRound += 0.6; coachKey = `coach_r3_pilot`; break;
                    case `suburb`:
                        bciDelta += 3; standingDelta += 1; spendThisRound += 0.4; coachKey = `coach_r3_suburb`; break;
                    case `broad`:
                        // Fast and wide — no containment; the effect drowns in external noise.
                        upliftDelta += 2; standingDelta -= 4; bciDelta -= 4; spendThisRound += 1.4; coachKey = `coach_r3_broad`; break;
                }

                // Control group — the counterfactual (decision tree #4).
                switch (d.control) {
                    case `rct`: bciDelta += 12; standingDelta += 8; break;
                    case `weak`: bciDelta += 2; standingDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r3_weakcontrol` : coachKey; break;
                    case `none`: ds.noControlRun = true; bciDelta -= 12; standingDelta -= 8; coachKey = `coach_r3_nocontrol`; break;
                }

                // Proportionate enforcement still belongs (decision tree #5).
                switch (d.enforce) {
                    case `targeted`: standingDelta += 5; bciDelta += 5; upliftDelta += 1; break;
                    case `dropall`: standingDelta -= 3; upliftDelta -= 1; coachKey = (coachKey === `coach_default`) ? `coach_r3_dropall` : coachKey; break;
                    case `punishall`: ds.coercionRun = true; standingDelta -= 7; bciDelta -= 4; coachKey = `coach_r3_punishall`; break;
                }

                // Speed-over-rigour pressure. With no control, high speed makes the result indefensible.
                if (d.speed >= 70) {
                    if (d.control === `none` || d.scope === `broad`) { ds.noControlRun = true; standingDelta -= 5; bciDelta -= 4; }
                    else { standingDelta -= 1; }
                } else if (d.speed <= 30 && (d.scope === `pilot` || d.scope === `multiarm`)) {
                    standingDelta += 2; bciDelta += 2;
                }

                summaryKey = ((d.scope === `pilot` || d.scope === `multiarm`) && d.control === `rct` && d.enforce === `targeted`) ? `sum_r3_good` :
                             (ds.noControlRun ? `sum_r3_nocontrol` :
                             (d.enforce === `punishall` ? `sum_r3_punish` : `sum_r3_weak`));
            } else if (round === 4) {
                // Round 4 — Read results & scale responsibly (Common Errors 5 & 6).
                switch (d.read) {
                    case `hetero`:
                        bciDelta += 10; standingDelta += 4; coachKey = `coach_r4_hetero`; break;
                    case `ignore`:
                        bciDelta -= 3; standingDelta -= 2; coachKey = `coach_r4_ignore`; break;
                    case `average`:
                        // Reading only the average is how a boomerang gets scaled to 1.4M people.
                        bciDelta -= 6; standingDelta -= 3; coachKey = `coach_r4_average`; break;
                }

                switch (d.scale) {
                    case `selective`:
                        upliftDelta += 5; bciDelta += 8; standingDelta += 6; coachKey = (d.read === `hetero`) ? `coach_r4_selective` : coachKey; break;
                    case `scaleall`:
                        // Scaling the backfired nudge state-wide — the boomerang at scale.
                        ds.backfireScaled = true; upliftDelta -= 3; standingDelta -= 10; bciDelta -= 8; coachKey = `coach_r4_scaleall`; break;
                    case `stopall`:
                        // Over-correcting back to enforcement abandons the whole behavioural case.
                        upliftDelta -= 4; bciDelta -= 6; standingDelta -= 4; coachKey = `coach_r4_stopall`; break;
                }

                switch (d.pitch) {
                    case `evidence`:
                        standingDelta += 10; bciDelta += 5; if (d.scale === `selective`) coachKey = `coach_r4_evidence`; break;
                    case `spin`:
                        standingDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_spin` : coachKey; break;
                    case `reskin`:
                        ds.coercionRun = true; standingDelta -= 9; bciDelta -= 4; coachKey = `coach_r4_reskin`; break;
                }

                if (d.conviction >= 60) { standingDelta += 3; bciDelta += 2; }
                else if (d.conviction <= 25) { standingDelta -= 3; }

                summaryKey = (d.read === `hetero` && d.scale === `selective` && d.pitch === `evidence`) ? `sum_r4_good` :
                             (ds.backfireScaled ? `sum_r4_backfire` :
                             (d.scale === `stopall` ? `sum_r4_stop` : `sum_r4_weak`));
            }

            // ---- Apply raw deltas (clamped). ----
            ds.bci = Math.max(0, Math.min(100, Math.round(ds.bci + bciDelta)));
            ds.standing = Math.max(0, Math.min(100, Math.round(ds.standing + standingDelta)));
            ds.adoption = Math.max(0, Math.min(100, Math.round(ds.adoption + adoptionDelta)));

            // Spend & budget.
            spendThisRound = Math.round(spendThisRound * 100) / 100;
            ds.spent = Math.round((ds.spent + spendThisRound) * 100) / 100;
            ds.budgetLeft = Math.round((this.BUDGET_CAP - ds.spent) * 100) / 100;
            // Overspending the capped A$3M pilot is itself a credibility failure.
            if (ds.budgetLeft < 0) {
                ds.standing = Math.max(0, ds.standing - 6);
                ds.bci = Math.max(0, ds.bci - 4);
            }

            // ---- Uplift is DERIVED: a real compliance gain needs diagnosis-fit,
            // adoption, behaviour-change quality and defensible evidence. ----
            let upliftBase = Math.max(0, ds.uplift + upliftDelta);
            // Reward compounding once the model is sound.
            const adoptFactor = ds.adoption / 100;          // 0..1
            const bciFactor = ds.bci / 100;                 // 0..1
            upliftBase = upliftBase + (round >= 2 ? 3.2 * adoptFactor * bciFactor : 0);

            // ---- STICKY ERROR GATES: each capped error keeps the run from reaching the top. ----
            // Coercion in disguise: the headline anti-pattern. Cannot post a credible uplift,
            // and standing is crushed regardless of other good rounds.
            if (ds.coercionRun) {
                upliftBase = Math.min(upliftBase, 3.0);
                ds.standing = Math.min(ds.standing, 35);
                ds.bci = Math.min(ds.bci, 55);
            }
            // One-size nudge: the same message to opposite drivers; effect is muted and noisy.
            if (ds.oneSizeRun) {
                upliftBase = Math.min(upliftBase, 4.5);
                ds.bci = Math.min(ds.bci, 60);
            }
            // Channel mismatch: adoption near zero where it matters; uplift cannot land.
            if (ds.channelMismatchRun) {
                upliftBase = Math.min(upliftBase, 4.0);
                ds.adoption = Math.min(ds.adoption, 25);
            }
            // No control group: the regulator will not accept the number — evidence quality capped.
            if (ds.noControlRun) {
                ds.bci = Math.min(ds.bci, 58);
                ds.standing = Math.min(ds.standing, 55);
            }
            // Scaled a backfired nudge: net harm at scale.
            if (ds.backfireScaled) {
                upliftBase = Math.min(upliftBase, 3.5);
                ds.standing = Math.min(ds.standing, 40);
            }
            // Mis-targeted enabling nudge at the won't-comply core.
            if (ds.misTargeted) {
                upliftBase = Math.min(upliftBase, 5.0);
            }

            ds.uplift = Math.round(upliftBase * 10) / 10;

            ds.upliftHistory.push(ds.uplift);
            ds.bciHistory.push(ds.bci);
            ds.adoptionHistory.push(ds.adoption);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the composite score + grade letter to the reporting/grading layer
            // every period. express/results_utils.php::express_resolveDomainScore reads
            // domainState.performance.overallScore; express_extractHistory reads it per period.
            // Scoring is UNCHANGED - _composite() reuses the exact v1.0.0 formula.
            const _score = this._composite(ds);
            ds.performance = { overallScore: _score, grade: this._gradeLetter(_score) };

            return {
                period: state.currentPeriod,
                uplift: ds.uplift,
                upliftDelta: Math.round((ds.uplift - ds.upliftHistory[ds.upliftHistory.length - 2]) * 10) / 10,
                bci: ds.bci,
                bciDelta: Math.round(bciDelta),
                adoption: ds.adoption,
                budgetLeft: ds.budgetLeft,
                spent: ds.spent,
                standing: ds.standing,
                coercionRun: ds.coercionRun,
                noControlRun: ds.noControlRun,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: _score,
                score: _score
            };
        }

        _standingLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 65) return t(`standing_strong`);
            if (v >= 40) return t(`standing_mid`);
            return t(`standing_risk`);
        }

        _fmtMoney(v) {
            // A$ millions with two decimals; locale-aware decimal mark.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(2);
            const out = lang === `es` ? s.replace(`.`, `,`) : s;
            return `A$${out}M`;
        }

        _fmtUplift(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            const out = lang === `es` ? s.replace(`.`, `,`) : s;
            return `${out} pp`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`upliftDisplay`, `domainState.uplift`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.nudgesim-card-uplift`);
                if (card) {
                    card.classList.toggle(`nudgesim-uplift-good`, n >= self.UPLIFT_TARGET);
                    card.classList.toggle(`nudgesim-uplift-danger`, n < 3 && (window.mySimulation.state.currentPeriod || 1) >= 3);
                }
                return self._fmtUplift(n);
            });

            uiManager.bind(`bciDisplay`, `domainState.bci`, (v) => `${Math.round(Number(v))}`);
            uiManager.bind(`adoptDisplay`, `domainState.adoption`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`budgetDisplay`, `domainState.budgetLeft`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.nudgesim-card-budget`);
                if (card) card.classList.toggle(`nudgesim-budget-danger`, n < 0);
                return self._fmtMoney(Math.max(0, n));
            });

            uiManager.bind(`standingDisplay`, `domainState.standing`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.nudgesim-standing-bar`);
                if (bar) {
                    bar.classList.toggle(`nudgesim-standing-good`, n >= 65);
                    bar.classList.toggle(`nudgesim-standing-mid`, n >= 40 && n < 65);
                }
                return self._standingLabel(n);
            });

            // Segmentation slider readout.
            const se = document.getElementById(`segmentInput`);
            const seReadout = document.getElementById(`segmentReadout`);
            if (se && seReadout) {
                seReadout.textContent = se.value;
                se.addEventListener(`input`, function() { seReadout.textContent = se.value; });
            }

            // Speed slider readout.
            const sp = document.getElementById(`speedInput`);
            const spReadout = document.getElementById(`speedReadout`);
            if (sp && spReadout) {
                spReadout.textContent = sp.value;
                sp.addEventListener(`input`, function() { spReadout.textContent = sp.value; });
            }
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, en) => (t ? t(k) : en);
            return {
                nudgeTrajectoryChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_uplift`, `Compliance uplift (×5, pp)`),
                                data: [],
                                borderColor: `#16876f`,
                                backgroundColor: `rgba(22,135,111,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#16876f`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_bci`, `Behaviour-change index`),
                                data: [],
                                borderColor: `#0f9aa0`,
                                backgroundColor: `rgba(15,154,160,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#0f9aa0`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_adoption`, `Adoption rate (%)`),
                                data: [],
                                borderColor: `#2f7fc4`,
                                backgroundColor: `rgba(47,127,196,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f7fc4`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#3c545d`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#6b8189` }, grid: { color: `rgba(16,50,58,0.06)` },
                                title: { display: true, text: L(`chart_axis_scale`, `0–100`), color: `#6b8189` }
                            },
                            x: {
                                ticks: { color: `#6b8189` }, grid: { color: `rgba(16,50,58,0.04)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#6b8189` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.upliftHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Uplift is in pp (roughly 0–12) — scale ×5 to share the 0–100 axis.
            const upliftScaled = ds.upliftHistory.map((v) => Math.min(100, Math.round(v * 5)));
            return {
                nudgeTrajectoryChart: {
                    labels: labels,
                    datasets: [
                        { data: upliftScaled },
                        { data: ds.bciHistory.map((v) => Math.round(v)) },
                        { data: ds.adoptionHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // 0-100 composite - IDENTICAL formula to v1.0.0 getPerformanceSummary.
            const uplift = Math.round(ds.uplift * 10) / 10;
            const bci = Math.round(ds.bci);
            const adoption = Math.round(ds.adoption);
            const standing = Math.round(ds.standing);
            const upliftScore = Math.min(100, (uplift / 12) * 100);
            return Math.round(upliftScore * 0.28 + bci * 0.30 + adoption * 0.20 + standing * 0.22);
        }

        _verdictKey(ds, composite) {
            // Verdict tier -> i18n key. Thresholds IDENTICAL to v1.0.0 (labels now localized).
            const uplift = Math.round(ds.uplift * 10) / 10;
            const bci = Math.round(ds.bci);
            const adoption = Math.round(ds.adoption);
            const standing = Math.round(ds.standing);
            const budgetLeft = Math.round(ds.budgetLeft * 100) / 100;
            const anyError = ds.coercionRun || ds.oneSizeRun || ds.channelMismatchRun ||
                             ds.noControlRun || ds.backfireScaled || ds.misTargeted;
            const upliftStrong = uplift >= this.UPLIFT_TARGET;
            const adoptedWell = adoption >= 55;
            const credible = !ds.noControlRun && bci >= 70;
            const ethical = !ds.coercionRun && standing >= 60;
            const onBudget = budgetLeft >= 0;
            if (!anyError && upliftStrong && adoptedWell && credible && ethical && onBudget && composite >= 75) return `verdict_proven`;
            if (!ds.coercionRun && !ds.noControlRun && bci >= 62 && standing >= 55) return `verdict_credible`;
            if (ds.coercionRun) return `verdict_coercion`;
            if (ds.noControlRun) return `verdict_nocontrol`;
            if (ds.channelMismatchRun || ds.oneSizeRun || ds.misTargeted) return `verdict_misdiagnosed`;
            if (ds.backfireScaled) return `verdict_backfire`;
            if (composite >= 52) return `verdict_mixed`;
            return `verdict_regulator`;
        }

        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 75) return `B`;
            if (c >= 62) return `C`;
            if (c >= 50) return `D`;
            if (c >= 35) return `E`;
            return `F`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const uplift = Math.round(ds.uplift * 10) / 10;
            const bci = Math.round(ds.bci);
            const adoption = Math.round(ds.adoption);
            const standing = Math.round(ds.standing);
            const budgetLeft = Math.round(ds.budgetLeft * 100) / 100;

            // Any sticky error means the behavioural case is not proven.
            const anyError = ds.coercionRun || ds.oneSizeRun || ds.channelMismatchRun ||
                             ds.noControlRun || ds.backfireScaled || ds.misTargeted;

            const upliftStrong = uplift >= this.UPLIFT_TARGET;
            const adoptedWell = adoption >= 55;
            const credible = !ds.noControlRun && bci >= 70;
            const ethical = !ds.coercionRun && standing >= 60;
            const onBudget = budgetLeft >= 0;

            // Composite: uplift (scaled), behaviour-change index, adoption, standing — balanced.
            // v1.1.0: composite via shared helper so per-period persisted score == completion score.
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.coercionRun) pattern = `coercion`;
            else if (ds.noControlRun) pattern = `nocontrol`;
            else if (ds.channelMismatchRun) pattern = `channel`;
            else if (ds.oneSizeRun || ds.misTargeted) pattern = `onesize`;
            else if (ds.backfireScaled) pattern = `backfire`;
            else if (upliftStrong && adoptedWell && credible && ethical) pattern = `behavioural`;

            // v1.1.0: verdict tier -> localized label via shared helper (thresholds unchanged).
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const verdictKey = this._verdictKey(ds, composite);
            const performance = T(verdictKey);

            const insights = [];
            if (verdictKey === `verdict_proven`) insights.push(window.mySimulation.t(`insight_behavioural`));
            else if (pattern === `coercion`) insights.push(window.mySimulation.t(`insight_coercion`));
            else if (pattern === `nocontrol`) insights.push(window.mySimulation.t(`insight_nocontrol`));
            else if (pattern === `channel`) insights.push(window.mySimulation.t(`insight_channel`));
            else if (pattern === `onesize`) insights.push(window.mySimulation.t(`insight_onesize`));
            else if (pattern === `backfire`) insights.push(window.mySimulation.t(`insight_backfire`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!ds.diagnosisLed) insights.push(window.mySimulation.t(`insight_nodiagnosis`));
            if (!onBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (!ethical && !ds.coercionRun) insights.push(window.mySimulation.t(`insight_standing_low`));
            if (upliftStrong && credible && ethical && !anyError) insights.push(window.mySimulation.t(`insight_evidence`));

            return {
                uplift: uplift,
                bci: bci,
                adoption: adoption,
                standing: standing,
                budgetLeft: budgetLeft,
                upliftStrong: upliftStrong,
                adoptedWell: adoptedWell,
                credible: credible,
                ethical: ethical,
                onBudget: onBudget,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                verdictKey: verdictKey,
                grade: this._gradeLetter(composite),
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const s = summary || {};
            const score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            const grade = s.grade || '';
            const verdict = s.performance || (s.verdictKey ? T(s.verdictKey) : '');
            const uplift = this._fmtUplift(Number(s.uplift || 0));
            const bci = Math.round(Number(s.bci || 0));
            const adoption = Math.round(Number(s.adoption || 0));
            const standing = this._standingLabel(Number(s.standing || 0));
            const budget = this._fmtMoney(Math.max(0, Number(s.budgetLeft || 0)));
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map((t) => '<li>' + t + '</li>').join('');
            const proven = s.verdictKey === 'verdict_proven';
            const badgeCls = proven ? 'ntc-cm-yes' : (score >= 62 ? 'ntc-cm-mid' : 'ntc-cm-no');
            const metric = (val, lab) => '<div class="ntc-cm-metric"><span class="ntc-cm-mv">' + val + '</span><span class="ntc-cm-ml">' + lab + '</span></div>';
            const metrics = metric(uplift, T('cm_m_uplift'))
                + metric(bci, T('cm_m_bci'))
                + metric(adoption + '%', T('cm_m_adoption'))
                + metric(standing, T('cm_m_standing'))
                + metric(budget, T('cm_m_budget'));
            return ''
                + '<div class="ntc-completion">'
                +   '<div class="ntc-cm-head">'
                +     '<div class="ntc-cm-score">' + score + '<span class="ntc-cm-score-max">/100</span></div>'
                +     '<div class="ntc-cm-grade">' + verdict + ' <span class="ntc-cm-badge ' + badgeCls + '">' + T('cm_grade') + ' ' + grade + '</span></div>'
                +   '</div>'
                +   '<div class="ntc-cm-metrics">' + metrics + '</div>'
                +   '<div class="ntc-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="ntc-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.coercionRun) return window.mySimulation.t(`hint_coercion`);
            if (ds.channelMismatchRun) return window.mySimulation.t(`hint_channel`);
            if (ds.oneSizeRun || ds.misTargeted) return window.mySimulation.t(`hint_onesize`);
            if (ds.noControlRun) return window.mySimulation.t(`hint_nocontrol`);
            if (ds.standing < 35) return window.mySimulation.t(`hint_standing`);
            if (ds.uplift >= this.UPLIFT_TARGET && ds.bci >= 70 && ds.standing >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.uplift`, label: `Uplift`, i18nKey: `col_uplift`, formatter: (v) => self._fmtUplift(Number(v)) },
                { key: `results.bci`, label: `BCI`, i18nKey: `col_bci`, formatter: (v) => `${Math.round(Number(v))}` },
                { key: `results.adoption`, label: `Adoption`, i18nKey: `col_adoption`, formatter: (v) => `${Math.round(Number(v))}%` },
                { key: `results.standing`, label: `Standing`, i18nKey: `col_standing`, formatter: (v) => self._standingLabel(Number(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

